using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns approximate number of chats in a being created chat folder. Main and archive chat lists must be fully preloaded for this function to work correctly
    /// </summary>
    public Task<TdLib.TdApi.Objects.Count> GetChatFolderChatCountAsync(ChatFolder folder = default)
    {

           using var activity =  StartCallActivity("GetChatFolderChatCountAsync", typeof(GetChatFolderChatCount).FullName ?? "GetChatFolderChatCountAsync");

           try
           {
             return client.GetChatFolderChatCountAsync(folder);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
